        data: {"result": {"minY": 0.1, "minX": 1.78263696E12, "maxY": 7.05, "series": [{"data": [[1.78263708E12, 7.05], [1.7826372E12, 3.65], [1.78263702E12, 5.683333333333334], [1.78263714E12, 6.783333333333333], [1.78263696E12, 0.9166666666666666]], "isOverall": false, "label": "Transaction-success", "isController": false}, {"data": [[1.78263708E12, 0.1], [1.7826372E12, 0.7333333333333333], [1.78263714E12, 0.3333333333333333]], "isOverall": false, "label": "Transaction-failure", "isController": false}], "supportsControllersDiscrimination": true, "granularity": 60000, "maxX": 1.7826372E12, "title": "Total Transactions Per Second"}},
